1	package service_test
2	
3	import (
4		"errors"
5		"testing"
6	
7		"github.com/Bob-xisuke/orb-registry-catalog/internal/service"
8	)
9	
10	// customStore is a caller-supplied storage implementation written entirely
11	// against the exported service contract: it never imports internal/store and
12	// uses none of its types. It proves a third party can back the business layer
13	// with its own backend by satisfying service.Store.
14	type customStore struct {
15		records []service.Record
16		index   map[string]int // repository + "\x00" + digest
17		tags    map[string]map[string]string
18		fault   error
19	}
20	
21	func newCustomStore() *customStore {
22		return &customStore{
23			index: make(map[string]int),
24			tags:  make(map[string]map[string]string),
25		}
26	}
27	
28	func customID(repo, digest string) string { return repo + "\x00" + digest }
29	
30	func (c *customStore) Register(in service.Record) (service.Record, service.RegisterStatus, error) {
31		if c.fault != nil {
32			return service.Record{}, 0, c.fault
33		}
34		if i, ok := c.index[customID(in.Repository, in.Digest)]; ok {
35			ex := c.records[i]
36			if ex.Tag == in.Tag && ex.SignatureVerified == in.SignatureVerified &&
37				ex.RetentionDays == in.RetentionDays && ex.SizeBytes == in.SizeBytes {
38				return ex, service.StatusDuplicate, nil
39			}
40			return service.Record{}, service.StatusConflict, nil
41		}
42		c.index[customID(in.Repository, in.Digest)] = len(c.records)
43		c.records = append(c.records, in)
44		if c.tags[in.Repository] == nil {
45			c.tags[in.Repository] = make(map[string]string)
46		}
47		c.tags[in.Repository][in.Tag] = in.Digest
48		return in, service.StatusCreated, nil
49	}
50	
51	func (c *customStore) ListRecords(repo string) ([]service.Record, error) {
52		if c.fault != nil {
53			return nil, c.fault
54		}
55		var out []service.Record
56		for _, r := range c.records {
57			if r.Repository == repo {
58				out = append(out, r)
59			}
60		}
61		return out, nil
62	}
63	
64	func (c *customStore) RecordByDigest(repo, digest string) (service.Record, error) {
65		if c.fault != nil {
66			return service.Record{}, c.fault
67		}
68		if i, ok := c.index[customID(repo, digest)]; ok {
69			return c.records[i], nil
70		}
71		return service.Record{}, service.ErrRecordNotFound
72	}
73	
74	func (c *customStore) RecordByTag(repo, tag string) (service.Record, error) {
75		if c.fault != nil {
76			return service.Record{}, c.fault
77		}
78		digest, ok := c.tags[repo][tag]
79		if !ok {
80			return service.Record{}, service.ErrRecordNotFound
81		}
82		return c.records[c.index[customID(repo, digest)]], nil
83	}
84	
85	// TestAlternativeStorePlugsIn wires a fully custom service.Store into the
86	// business layer and exercises the same created / duplicate / conflict /
87	// not-found / storage behavior the SQLite adapter provides, confirming the
88	// business outcomes depend only on the port.
89	func TestAlternativeStorePlugsIn(t *testing.T) {
90		st := newCustomStore()
91		var _ service.Store = st // the custom backend satisfies the exported port
92		svc := service.New(st)
93	
94		reg := service.RegisterInput{
95			Repository:        "team/app",
96			Digest:            sqliteDigestA,
97			Tag:               "latest",
98			SignatureVerified: true,
99			RetentionDays:     30,
100			SizeBytes:         1024,
101		}
102	
103		first, err := svc.Register(reg)
104		if err != nil || first.Outcome != service.OutcomeCreated {
105			t.Fatalf("first register = %+v, %v; want created", first, err)
106		}
107	
108		dup, err := svc.Register(reg)
109		if err != nil || dup.Outcome != service.OutcomeDuplicate ||
110			dup.Artifact.PushedAt != first.Artifact.PushedAt {
111			t.Fatalf("duplicate = %+v, %v; want duplicate with original pushed_at", dup, err)
112		}
113	
114		// A different digest under the same tag moves the pointer; the old record
115		// survives by digest.
116		regB := reg
117		regB.Digest = sqliteDigestB
118		regB.SizeBytes = 2048
119		if _, err := svc.Register(regB); err != nil {
120			t.Fatalf("register B: %v", err)
121		}
122		byTag, err := svc.Query(service.Query{Kind: service.QueryByTag, Repository: "team/app", Tag: "latest"})
123		if err != nil || len(byTag) != 1 || byTag[0].Digest != sqliteDigestB {
124			t.Fatalf("tag = %+v, %v; want B", byTag, err)
125		}
126		byDigest, err := svc.Query(service.Query{Kind: service.QueryByDigest, Repository: "team/app", Digest: sqliteDigestA})
127		if err != nil || len(byDigest) != 1 || byDigest[0] != first.Artifact {
128			t.Fatalf("digest lookup = %+v, %v; want original A", byDigest, err)
129		}
130	
131		// Repository list stays in first-registration order.
132		list, err := svc.Query(service.Query{Kind: service.QueryByRepository, Repository: "team/app"})
