	st, err := store.Open(path)
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	return service.New(st), st, path
}

func sqliteValidInput(repo, digest, tag string) service.RegisterInput {
	return service.RegisterInput{
		Repository:        repo,
		Digest:            digest,
		Tag:               tag,
		SignatureVerified: true,
		RetentionDays:     30,
		SizeBytes:         1024,
